package com.mfg.qms.controller;import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.qms.entity.DefectRecord;import com.mfg.qms.repo.*;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/qms/defects") @RequiredArgsConstructor public class DefectController{private final DefectRecordRepository defects;private final InspectionRepository inspections;@GetMapping public ApiResponse<Page<DefectRecord>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(defects.findAll(PageRequest.of(Math.max(0,page-1),Math.min(200,size))));}@PostMapping public ApiResponse<DefectRecord> create(@RequestBody DefectRecord d){if(defects.existsByDefectNo(d.getDefectNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"不合格品单号已存在");var inspection=inspections.findAll().stream().filter(x->d.getInspectionNo().equals(x.getInspectionNo())).findFirst().orElseThrow(()->BizException.of(ErrorCode.MASTER_DATA_NOT_FOUND,"检验单不存在"));if(d.getDefectQty().compareTo(inspection.getDefectQty())>0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"不合格数量不能超过检验不良数量");d.setMaterialCode(inspection.getMaterialCode());return ApiResponse.ok(defects.save(d));}@PostMapping("/{id}/disposition")public ApiResponse<DefectRecord> disposition(@PathVariable Long id,@RequestParam String action,@RequestParam BigDecimal qty){DefectRecord d=defects.findById(id).orElseThrow(()->BizException.notFound("不合格品",id));if(!java.util.Set.of("REWORK","SCRAP","CONCESSION","RETURN").contains(action))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"非法处置方式");if(qty.compareTo(d.getDefectQty())>0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"处置数量不能超过不合格数量");d.setDisposition(action);d.setDispositionQty(qty);d.setDispositionAt(LocalDateTime.now());d.setDispositionBy(CurrentUser.usernameOrSystem());return ApiResponse.ok(defects.save(d));}}
